import openpyxl,re
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx')
# helper normalize
def norm(name):
    if not name:
        return ''
    s=name.split(':')[0].strip()
    # remove phrases
    phrases=[
        'International Reserves','Intl Reserves','Official Reserve Assets','Foreign Reserves',
        'Reserve Assets','International Reserve Assets','Intl Reserves','Intl Res.','International Reserves'
    ]
    for p in phrases:
        s=re.sub(r'\b'+re.escape(p)+r'\b','',s,flags=re.I).strip()
    # collapse spaces
    s=' '.join(s.split())
    return s

# Value
ws=wb['Value']
row_2025=None
for r in range(10,ws.max_row+1):
    if str(ws.cell(r,1).value)=='2025':
        row_2025=r;break
headers=[ws.cell(1,c).value for c in range(1,ws.max_column+1)]
values=[ws.cell(row_2025,c).value for c in range(1,ws.max_column+1)]
value_countries={}
for c in range(3,ws.max_column+1):
    val=values[c-1]
    if val is None:
        continue
    h=headers[c-1]
    if not h:
        continue
    country=norm(h)
    value_countries[country]=val
print('Value countries',value_countries)

# Volume
ws=wb['Volume']
row_2025=None
for r in range(10,ws.max_row+1):
    if str(ws.cell(r,1).value)=='2025':
        row_2025=r;break
headers=[ws.cell(1,c).value for c in range(1,ws.max_column+1)]
values=[ws.cell(row_2025,c).value for c in range(1,ws.max_column+1)]
volume_countries={}
for c in range(3,ws.max_column+1):
    val=values[c-1]
    if val is None:
        continue
    h=headers[c-1]
    if not h:
        continue
    country=norm(h)
    volume_countries[country]=(val,h)
print('Volume countries',volume_countries)

# additional
additional={k:v for k,v in volume_countries.items() if k not in value_countries}
print('Additional',additional)
